// Build Client Vars: the strings the Drive and Slack legs are built from, all derived from the
// one client name on the launch row, plus the contact emails the Shared folder is shared with.
// Kept as its own node because every Drive and Slack parameter downstream reads it by name.
const p = $('Launch Params').first().json || {};
const clientName = p.clientName || 'Unknown Client';
const slug = clientName.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const channelName = slug + '-private';
// The Contacts search: one item per contact, or one empty placeholder item when the launch row
// named nobody. An address only counts once.
const emails = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const e = j.email || (j.fields && j.fields.email) || '';
  if (e && emails.indexOf(e) < 0) emails.push(e);
}
const sections = ['Offer & info source', 'Infrastructure', 'List building', 'Outreach', 'Sequencer', 'Copy', 'Scheduler', 'Inbox management', 'Automations', 'Communication'];
const overrides = '# Overrides - ' + clientName + '\n\n' + sections.map((s) => '## ' + s).join('\n\n') + '\n';
return [{ json: { clientName, slug, channelName, emails, overrides, extras: p.extras || [], base: p.base || '' } }];

const emails = $('Build Client Vars').first().json.emails || [];
const sharedId = $('Create Shared').first().json.id;
return emails.map(email => ({ json: { email, sharedId } }));

// Scaffold Register: the List Building 2.0 field register (Flowroots/Operations/List Building
// 2.0.md, "Fields"; the laws in Flowroots/Operations/Field Standard.md), the one copy every client
// base is scaffolded from. Pure data, read twice here: Create ClayRoots Base seeds the new base
// with Companies' plain fields (the seed), and Plan Scaffold Pass walks the whole register every
// pass. Every other machine that needs a field definition gets this file inlined at push time by
// the `// @@register` directive in scripts/n8n-push.js (as `const REGISTER`); REGISTER.md at the
// repo root is compiled from it by scripts/register.js. Nothing else defines a field.
// Table descriptions stay empty: the description is reserved for the share link. The views are
// declared here as data (name, filter, fields, sort) so the register is their spec too; making
// them in a base, like the two synced mirrors ("<Client> Campaigns", "<Client> Signals"), is the
// Operator's manual act, never made here.
// The Hub side (ruled 2026-09-02). Clients carries the only per-client table pointers:
// ClayrootsCompaniesTableID, ClayrootsPeopleTableID, ClayrootsCompaniesSharedView,
// ClayrootsPeopleSharedView. A machine that takes Table takes it by name (People or Companies) and
// resolves it in the client's base; a machine that needs an id reads those four. Signals.View is the
// Airtable view id of the queue view the signal feeds, on the table named by Campaigns.Table
// (People for a lead feed, Companies for a company feed). No other Hub field points at a client
// table or view.
//
// Field kinds. plain: type + options, created with its table or as a column. formula: refs are
// field names on the same table, swapped for field ids at plan time. link: to a register table.
// mirrorLink: to the client's synced mirror when the base carries it, else a counted skip.
// lookup / count / rollup: through a link, resolved by the linked table's id, never by name.
// mirrorLookup: a lookup through a mirrorLink instead of through the Companies link. It resolves
// by the mirror's own table (whose name carries the client's name), so it names `mirror`, the way
// mirrorLink does, and never `via`, the way every Companies lookup does. Same skip rule as
// mirrorLink: no mirror in the base, no field.
const SEL=(choices)=>({ choices: choices.map(c=>typeof c==='string'?{name:c}:c) });
const txt=(name)=>({ name, kind:'plain', type:'singleLineText' });
const long=(name)=>({ name, kind:'plain', type:'multilineText' });
const sel=(name,choices)=>({ name, kind:'plain', type:'singleSelect', options:SEL(choices) });
const dt=(name)=>({ name, kind:'plain', type:'dateTime', options:{ dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc' } });
const day=(name)=>({ name, kind:'plain', type:'date', options:{ dateFormat:{name:'iso'} } });
const num=(name,precision)=>({ name, kind:'plain', type:'number', options:{ precision:precision||0 } });
const chk=(name)=>({ name, kind:'plain', type:'checkbox', options:{ color:'greenBright', icon:'check' } });
const url=(name)=>({ name, kind:'plain', type:'url' });
const formula=(name,f,refs,description)=>({ name, kind:'formula', formula:f, refs:refs||[], description });
const lookup=(name)=>({ name, kind:'lookup', via:'Companies', field:name });
const mirrorLookup=(name,mirror,field,description)=>({ name, kind:'mirrorLookup', mirror, field, description });
// Sequencers, the one mirror-derived lookup, on both Companies and People through their own
// Campaigns link. It names which senders already hold this row. Plural on purpose: a row can link
// several campaigns, so the value is a list ("PlusVibe, PlusVibe" or "Alta, PlusVibe"), and the
// name says so at a glance. The mirror's own column stays `Sequencer`, singular, because one
// campaign really does have one sender. A live view tests this list with does-not-contain, never
// equals: a campaign-feeding view excludes only its own sender, because a person already in an
// Alta campaign is still a legitimate target for a PlusVibe one, and the reverse.
const SEQUENCERS=()=>mirrorLookup('Sequencers','Campaigns','Sequencer',
  'The senders that already hold this row, one per linked campaign. A campaign-feeding view excludes only its own sender with a does-not-contain test, so the same person can legitimately sit in campaigns on two different senders.');
// about: a Companies field that describes the company. The On People rule (ruled 2026-09-02):
// every such field is on People as a lookup of the identical name, generated below from this flag,
// never typed by hand. A Companies field without the flag stays off People.
const about=(f)=>Object.assign(f,{ company:true });

// Palettes (Field Standard, "Shared vocabularies", ruled 2026-09-02). A choice has one color, the
// same in every base; colors are part of the definition. The four shared palettes:
//   verdict  the email lane (MV, BB, Status) and Campaign Status: green good, yellow risky, red bad,
//            orange error, blue in progress, gray unknown or skipped
//   source   Contact Source: one color per provider, the same everywhere
//   scale    Employees: a ramp, small to large
//   rank     Seniority: by decision power
// Email Source keeps the waterfall's tier colors (TIER). Department and DNC Reason carry their
// own per-choice maps (DEPARTMENT_COLOR: families share a hue; DNC_COLOR).
const VERDICT={ ok:'greenBright', done:'greenBright', deliverable:'greenBright', COMPLETED:'greenBright', catch_all:'yellowBright', risky:'yellowBright', invalid:'redBright', undeliverable:'redBright', no_email_found:'redBright', BOUNCED:'redBright', error:'orangeBright', UNSUBSCRIBED:'orangeBright', verifying:'blueBright', IN_SEQUENCE:'blueBright', REPLIED:'purpleBright', disposable:'orangeLight2', unknown:'grayBright', skipped:'grayLight2', NEVER_CONTACTED:'grayLight2' };
const SOURCE={ ContaGen:'blueLight2', Supersoniq:'purpleLight2', 'AI-Ark':'tealLight2' };
const SCALE={ '1-10':'blueLight2', '11-50':'cyanLight2', '51-200':'tealLight2', '201-500':'greenLight2', '501-1000':'yellowLight2', '1001-5000':'orangeLight2', '5001-10000':'redLight2', '10001+':'purpleLight2' };
const RANK={ 'C-Suite':'purpleLight2', Founder:'purpleLight2', Owner:'purpleLight2', President:'purpleLight2', Executive:'purpleLight2', VP:'blueLight2', 'EVP / SVP':'blueLight2', Head:'cyanLight2', Director:'cyanLight2', Manager:'tealLight2', Senior:'greenLight2', Partner:'yellowLight2', 'Board / Chair':'yellowLight2', Unclassified:'grayLight2' };
const TIER={ P0:'blueBright', P1:'cyanBright', P2:'tealBright', P3:'purpleBright', none:'grayBright' };
const DEPARTMENT_COLOR={ Executive:'purpleLight2', Strategy:'purpleLight1', Engineering:'blueLight2', Product:'blueLight1', Technology:'cyanLight2', Data:'cyanLight1', 'R&D':'tealLight2', Security:'tealLight1', Sales:'greenLight2', Marketing:'greenLight1', 'Customer Success':'yellowLight2', Communications:'yellowLight1', Operations:'orangeLight2', 'Project Management':'orangeLight1', Finance:'redLight2', 'Supply Chain':'redLight1', Design:'pinkLight2', 'Human Resources':'pinkLight1', 'Community & Social':'pinkBright', Legal:'grayLight2', 'Compliance & GRC':'grayLight1' };
const DNC_COLOR={ Customer:'greenLight2', 'Not interested':'redLight2', 'Client request':'orangeLight2', 'Active deal':'blueLight2' };
// paint: names -> choices with their palette color. A value the palette does not name is a register
// defect and fails here, at scaffold time, never as an uncolored choice in a client base.
const paint=(names,palette)=>names.map(n=>{ const color=typeof palette==='string'?palette:palette[n]; if(!color) throw new Error('Scaffold Register: no palette color for "'+n+'"'); return { name:n, color }; });

// The email lane. Choices and colors exactly as the waterfall has always declared them; Field List
// in Waterfall Emails and Verify Emails reads them from here. People carries the whole lane
// (LANE, Email in its own place in the table's order); Companies carries the short lane
// (COMPANY_LANE, ruled 2026-09-02): Email, MV P0, BB, Final Email, Status, the same choices and colors.
const MV=paint(['ok','catch_all','invalid','disposable','unknown','error','skipped'],VERDICT);
const BB=paint(['verifying','deliverable','undeliverable','risky','unknown','error','skipped'],VERDICT);
const SRC=paint(['P0','P1','P2','P3','none'],TIER);
const ST=paint(['done','verifying','no_email_found','error'],VERDICT);
const LANE=()=>[ sel('MV P0',MV), txt('P1 (Trykitt)'), sel('MV P1',MV), txt('P2 (LeadMagic)'), sel('MV P2',MV), txt('P3 (Prospeo)'), sel('MV P3',MV), sel('BB',BB), txt('Final Email'), sel('Email Source',SRC), sel('Status',ST) ];
const COMPANY_LANE=()=>[ txt('Email'), sel('MV P0',MV), sel('BB',BB), txt('Final Email'), sel('Status',ST) ];

// The machine fields the leads sync and the deploy doors write, as Sync PlusVibe Leads declares them.
const CAMPAIGN_STATUS=paint(['NEVER_CONTACTED','IN_SEQUENCE','COMPLETED','REPLIED','BOUNCED','UNSUBSCRIBED'],VERDICT);
const MACHINE=()=>[ num('Messages Sent'), dt('Last Contacted'), sel('Campaign Status',CAMPAIGN_STATUS), txt('Bounce Reason'), dt('Synced At'), txt('Deploy Error') ];

const EMPLOYEES=paint(['1-10','11-50','51-200','201-500','501-1000','1001-5000','5001-10000','10001+'],SCALE);
const SENIORITY=paint(['C-Suite','Founder','Owner','President','Executive','VP','Head','Director','Manager','Senior','Partner','EVP / SVP','Board / Chair','Unclassified'],RANK);
// Department: Dave's live list, the register (ruled 2026-09-02); Build People in Waterfall Contacts Batch maps into it.
const DEPARTMENT=paint(['Executive','Engineering','Technology','R&D','Product','Data','Security','Design','Operations','Sales','Marketing','Finance','Human Resources','Customer Success','Project Management','Strategy','Legal','Supply Chain','Communications','Community & Social','Compliance & GRC'],DEPARTMENT_COLOR);
const CONTACT_SOURCE=paint(['ContaGen','Supersoniq','AI-Ark'],SOURCE);
const DNC_REASON=paint(['Customer','Not interested','Client request','Active deal'],DNC_COLOR);

// relevance: the placeholder the Operator replaces per client with the client's buyer rule.
// manually_approved always passes; the rule is the rest of the OR. The description below is the
// one place this reaches a reader who never opens this file: it renders into REGISTER.md and,
// once a base is scaffolded, into the field itself in Airtable, so it has to say the same thing
// there that this comment says here.
const COMPANY_RELEVANCE='IF(OR({manually_approved}, {public_emails_clean} != ""), 1, 0)';
const COMPANY_RELEVANCE_DESCRIPTION='Placeholder: every client must replace this with their own buyer rule. As shipped it passes manually_approved rows plus any row carrying a public email (public_emails_clean not blank). Until the client\'s rule replaces it, relevance-filtered views on this table (Not Waterfalled, Not Found, Found, Found : Campaigns) show only rows that happen to clear that default, not a configured buyer rule.';
const PEOPLE_RELEVANCE='IF(OR({manually_approved}, FALSE()), 1, 0)';
const PEOPLE_RELEVANCE_DESCRIPTION='Placeholder: every client must replace this with their own buyer rule. As shipped the OR\'s second half is always FALSE, so nothing passes except rows ticked manually_approved by hand. Until the client\'s rule replaces it, every relevance-filtered view on this table (Relevant, Not Waterfalled, Not Found, Found, Found : Campaigns, Found : Never Contacted, Signals) stays empty.';
// linkedin_name_match: 1 when the LinkedIn URL slug (after /in/, letters only) contains the
// cleaned first or last name (letters only), else 0. Blank name or blank URL is 0.
const SLUG='REGEX_REPLACE(REGEX_REPLACE(REGEX_REPLACE(LOWER({LinkedIn URL}), "^.*/in/", ""), "[/?#].*$", ""), "[^a-z]", "")';
const NAME=(f)=>'REGEX_REPLACE(LOWER({'+f+'}), "[^a-z]", "")';
const HIT=(f)=>'AND(LEN('+NAME(f)+') > 0, FIND('+NAME(f)+', '+SLUG+') > 0)';
const LINKEDIN_NAME_MATCH='IF(AND({LinkedIn URL}, OR({first_name}, {last_name})), IF(OR('+HIT('first_name')+', '+HIT('last_name')+'), 1, 0), 0)';

// Views (ruled 2026-09-02): name, filter (in words and as an Airtable formula), the visible fields
// in order, sort. Build Date descending everywhere it exists; DNC has no Build Date and sorts by Added.
// The standard set below is a reporting set: every one of them describes a state of the table, and
// "Found : Campaigns" and "Found : Never Contacted" are read, not fed from. "Never Contacted" reads
// Messages Sent = 0, which is a fact about the row, not an exclusion rule.
// A campaign-feeding view is the Operator's, made per campaign on top of these, and it excludes per
// sender, never blanket (ruled 2026-09-03). Being in some other campaign is not a reason to skip a
// person: someone already enrolled on Alta is still a legitimate target on PlusVibe, and the
// reverse. The exclusion filter is Sequencers does-not-contain the campaign's own sender, and only
// that. Sequencers is a list (a row can link several campaigns), so it is never tested with equals,
// and a Campaigns-is-empty filter is wrong wherever it appears.
const view=(name,words,f,fields,sortField)=>({ name, filter:{ words, formula:f }, fields, sort:{ field:sortField||'Build Date', direction:'desc' } });
const RELEVANT='{relevance} = 1';
const NOT_WATERFALLED='AND({relevance} = 1, NOT({Status}))';
const NOT_FOUND='AND({relevance} = 1, OR({Status} = "no_email_found", {Status} = "error"))';
const FOUND='AND({relevance} = 1, {Status} = "done")';
const SIGNALS='AND({relevance} = 1, {Signals} != BLANK())';

const COMPANY_COVERAGE=['Domain','Company','Description','Employees','Tag','Contacts Count','Contact Sources','Contacts Pulled At','Build Date'];
const COMPANY_EMAILS=['Domain','Company','Description','Tag','public_emails_clean','Email','MV P0','BB','Final Email','Status','Build Date'];
const COMPANIES={ name:'Companies', primary:'Domain', fields:[
  ...[ txt('Domain'), txt('Company'), long('Description'), txt('Industry Groups'), txt('Business Model'),
    sel('Employees',EMPLOYEES), txt('Revenue Range'), txt('Keywords'),
    txt('Country'), txt('State'), txt('City'), txt('Street'), txt('Zip'),
    txt('Phones'), txt('Public Emails'), txt('Social URLs'), txt('public_emails_clean'),
    txt('MX Provider'), txt('Redirect Domain'),
    txt('Domain Source'), txt('Tag') ].map(about),
  formula('Build Date','CREATED_TIME()'),
  dt('Contacts Pulled At'),
  { name:'Contacts Count', kind:'count', via:'People' },
  { name:'Contact Sources', kind:'rollup', via:'People', field:'Contact Source', formula:'ARRAYUNIQUE(values)' },
  about({ name:'Signals', kind:'mirrorLink', mirror:'Signals' }),
  about(dt('Signal At')), about(long('ICP Reason')),
  ...COMPANY_LANE(),
  { name:'Campaigns', kind:'mirrorLink', mirror:'Campaigns' }, SEQUENCERS(),
  ...MACHINE(), chk('manually_approved'),
  formula('relevance',COMPANY_RELEVANCE,['manually_approved','public_emails_clean'],COMPANY_RELEVANCE_DESCRIPTION)
], views:[
  view('Not Sourced','Contacts Pulled At is empty','NOT({Contacts Pulled At})',COMPANY_COVERAGE),
  view('Not Covered','Contacts Pulled At is set and Contacts Count = 0','AND({Contacts Pulled At}, {Contacts Count} = 0)',COMPANY_COVERAGE),
  view('Covered','Contacts Count > 0','{Contacts Count} > 0',COMPANY_COVERAGE),
  view('Cut Review','relevance = 0','{relevance} = 0',['Domain','Company','Description','Employees','Tag','manually_approved','Build Date']),
  view('Not Waterfalled','relevance = 1 and Status is empty',NOT_WATERFALLED,COMPANY_EMAILS),
  view('Not Found','relevance = 1 and Status is no_email_found or error',NOT_FOUND,COMPANY_EMAILS),
  view('Found','relevance = 1 and Status = done',FOUND,COMPANY_EMAILS),
  view('Found : Campaigns','relevance = 1 and Status = done',FOUND,['Domain','Company','Description','Final Email','Tag','Campaigns','Campaign Status','Messages Sent','Last Contacted','Build Date'])
]};

// The On People rule, as code: every Companies field flagged `company` lands on People as a lookup
// of the identical name, in Companies' order.
const COMPANY_LOOKUPS=()=>COMPANIES.fields.filter(f=>f.company).map(f=>lookup(f.name));
const PEOPLE_EMAILS=['Name','Title','Company','Tag','Email','MV P0','P1 (Trykitt)','MV P1','P2 (LeadMagic)','MV P2','P3 (Prospeo)','MV P3','BB','Final Email','Email Source','Status','Build Date'];
const PEOPLE_CAMPAIGNS=['first_name','last_name','Title','Company','Description','Domain','Final Email','LinkedIn URL','Tag','Campaigns','Campaign Status','Messages Sent','Last Contacted','Build Date'];
// Signals, the signal queue (ruled 2026-09-03): the people whose company carries a signal, freshest
// signal on top. It reads the Relevant set plus the two signal fields, and it is the view a signal
// play is worked from.
// It CANNOT exist until the client's synced Signals mirror is in the base. The filter tests
// {Signals}, a lookup through the Companies link to Companies.Signals, and that is a mirrorLink: no
// mirror in the base, no field, so no view. Same rule as Sequencers and the Campaigns link. A
// freshly duplicated template base cannot carry this view; it belongs on the post-duplication
// checklist, beside the mirrors themselves, never in the template.
// Signal-play extras stay out of the list below. A client running the Hiring play also shows that
// group's Job Title, Job Posted and Existing In Role, which exist only when the group is picked; a
// client's own per-contact columns are the Operator's. Both are added on top, per client.
const PEOPLE_SIGNALS=['Name','Title','Seniority','Department','Company','Description','Employees','Email','LinkedIn URL','Contact Source','Tag','Signals','Signal At','Build Date'];
const PEOPLE={ name:'People', primary:'Name', after:[{table:'Companies'}], fields:[
  txt('Name'), txt('first_name'), txt('last_name'), txt('Title'),
  sel('Seniority',SENIORITY), sel('Department',DEPARTMENT),
  txt('Email'), url('LinkedIn URL'), txt('Phone'),
  { name:'Companies', kind:'link', table:'Companies' },
  txt('Contact Key'), sel('Contact Source',CONTACT_SOURCE), txt('Source ID'),
  formula('Build Date','CREATED_TIME()'),
  ...LANE(),
  chk('manually_approved'),
  formula('relevance',PEOPLE_RELEVANCE,['manually_approved'],PEOPLE_RELEVANCE_DESCRIPTION),
  formula('linkedin_name_match',LINKEDIN_NAME_MATCH,['LinkedIn URL','first_name','last_name']),
  ...COMPANY_LOOKUPS(),
  { name:'Campaigns', kind:'mirrorLink', mirror:'Campaigns' }, SEQUENCERS(),
  ...MACHINE()
], views:[
  view('Relevant','relevance = 1',RELEVANT,['Name','Title','Seniority','Department','Company','Description','Employees','Email','LinkedIn URL','Contact Source','Tag','Build Date']),
  view('Cut Review','relevance = 0','{relevance} = 0',['Name','Title','Seniority','Department','Company','Description','Employees','Tag','manually_approved','Build Date']),
  view('Not Waterfalled','relevance = 1 and Status is empty',NOT_WATERFALLED,PEOPLE_EMAILS),
  view('Not Found','relevance = 1 and Status is no_email_found or error',NOT_FOUND,PEOPLE_EMAILS),
  view('Found','relevance = 1 and Status = done',FOUND,PEOPLE_EMAILS),
  view('Found : Campaigns','relevance = 1 and Status = done',FOUND,PEOPLE_CAMPAIGNS),
  view('Found : Never Contacted','relevance = 1 and Status = done and Messages Sent = 0','AND({relevance} = 1, {Status} = "done", {Messages Sent} = 0)',PEOPLE_CAMPAIGNS),
  view('Signals','relevance = 1 and Signals is not empty. Needs the synced Signals mirror: the filter reads a lookup of Companies.Signals, a mirrorLink, so a base without the mirror cannot carry this view',SIGNALS,PEOPLE_SIGNALS,'Signal At')
]};

const DNC={ name:'DNC', primary:'Domain', after:[{table:'People', field:'Companies'}], fields:[
  txt('Domain'),
  sel('Reason',DNC_REASON),
  long('Notes'), day('Added')
], views:[
  view('Not Interested','Reason = Not interested','{Reason} = "Not interested"',['Domain','Reason','Notes','Added'],'Added'),
  view('From Client','Reason is not Not interested','{Reason} != "Not interested"',['Domain','Reason','Notes','Added'],'Added')
]};

// Declared extras (Field Standard, "Declared extras"): named groups on Companies the scaffold
// creates when the launch row picks the group; each owner machine writes only its own group and
// creates nothing. Types exactly as the page's table. Trustpilot Rating is shared by Storeleads
// and Reviews under the same name and type. Every extras field describes the company, so the On
// People rule applies: each group also brings its fields to People as lookups of the identical
// name, generated here from the Companies group, created with it when the group is picked.
const COMPANY_EXTRAS=[
  { group:'Storeleads', owner:'Insert Storeleads domains to Clayroots', table:'Companies', fields:[
    txt('Plan'), num('Revenue Est Monthly'), num('Store Age Years',1), num('Product Count'), num('App Spend Mo'),
    txt('Key Apps'), txt('Tech Stack'), num('Trustpilot Rating',1), num('Trustpilot Reviews'),
    txt('Migrated From'), txt('Social Followers'), txt('Growth 90d'), txt('Features')
  ]},
  { group:'Hiring', owner:'Handle Hiring Intent Signal', table:'Companies', fields:[
    txt('Job ID'), txt('Job Title'), url('Job Link'), day('Job Posted'), long('Job Description'),
    txt('Job Seniority'), txt('Job Function'), txt('Job Employment Type'), txt('Job Industries'),
    num('Job Applicants'), txt('Job Salary'), txt('Job Poster Name'), txt('Job Poster Title'),
    url('Job Poster LinkedIn'), num('Existing In Role')
  ]},
  { group:'Reviews', owner:'Handle Service Reviews Intent Signal', table:'Companies', fields:[
    num('Review Count'), day('Review Latest'), url('Review Link'), long('Review Titles'), long('Review Quotes'),
    txt('Review Replied'), num('Trustpilot Rating',1), num('Trustpilot Reviews Total'), url('Trustpilot URL')
  ]}
];
const EXTRAS=[ ...COMPANY_EXTRAS, ...COMPANY_EXTRAS.map(g=>({ group:g.group, owner:g.owner, table:'People', fields:g.fields.map(f=>lookup(f.name)) })) ];

// Guards: a duplicate name on a table, or a view naming a field the table does not carry, is a
// register defect and fails here, never as a half-made base.
const refs=(f)=>(String(f).match(/\{([^}]+)\}/g)||[]).map(s=>s.slice(1,-1));
for(const T of [COMPANIES,PEOPLE,DNC]){
  const have=new Set(T.fields.map(f=>f.name));
  if(have.size!==T.fields.length) throw new Error('Scaffold Register: duplicate field name on '+T.name);
  for(const v of T.views||[]) for(const n of [...v.fields, v.sort.field, ...refs(v.filter.formula)]) if(!have.has(n)) throw new Error('Scaffold Register: view "'+v.name+'" on '+T.name+' names "'+n+'", which the table does not carry');
}

const plain=(T)=>T.fields.filter(f=>f.kind==='plain').map(f=>{ const o={ name:f.name, type:f.type }; if(f.options) o.options=f.options; return o; });
return [{ json: { tables:[COMPANIES, PEOPLE, DNC], extras:EXTRAS, palettes:{ verdict:VERDICT, source:SOURCE, scale:SCALE, rank:RANK, tier:TIER, department:DEPARTMENT_COLOR, dncReason:DNC_COLOR }, seed:{ name:COMPANIES.name, fields:plain(COMPANIES) } } }];

// Scaffold Init: opens the scaffold state for this run (static data, reset at the trigger). The
// base and the client name come from Launch Params. This machine no longer creates a base and so
// seeds nothing: the base arrives as a duplicate of the CLAYROOTS SCHEMA template, already
// carrying Companies, People and DNC with their views, and the scaffold's whole job here is to
// find that, count it as existed, and add what the template deliberately leaves out. The launch's
// Extras picks (the Hub Automations `Extras` multi-select) name the declared extras groups the
// scaffold creates on top of the register (Operator ruling 2026-09-02); a pick the register does
// not declare is a counted failure, never a crash. Only reached when a base id is in hand, which
// Launch Params has already proven. One item out.
const sd = $getWorkflowStaticData('global');
const reg = $('Scaffold Register').first().json;
const p = $('Launch Params').first().json || {};
const base = String(p.base || '');
const clientName = String(p.clientName || '');
const picks = Array.isArray(p.extras) ? p.extras : [];
const S = { base: base, clientName: clientName, pass: 0, seen: {}, created: [], existed: [], skipped: [], failed: [], pending: [], extras: [], extrasPicked: picks.slice() };
const groups = reg.extras || [];
for (const pick of picks) {
  const g = groups.find(x => x.group === pick || x.choice === pick);
  if (!g) { S.failed.push('Extras: "' + pick + '" is not a declared group (the register declares ' + groups.map(x => x.group).join(', ') + '); nothing created for it'); continue; }
  if (S.extras.indexOf(g.group) < 0) S.extras.push(g.group);
}
sd.scaffold = S;
return [{ json: { base: base, extras: S.extras }, pairedItem: { item: 0 } }];

// Plan Scaffold Pass: one pass of the idempotent scaffold. Reads the base's live schema, walks
// the register (Scaffold Register) in order and emits one meta-API call per thing that is missing
// and creatable now: a table with its plain fields (primary first), or a single field. The
// dependencies set the order: People after Companies; the People link before the People lookups;
// the inverse link before the Companies count and rollup; the mirror link before the mirror
// lookup that reads through it; a formula after the fields it names;
// DNC after the People link. What exists is left alone and counted as a skip. A column of
// another type, or a case variant of the name, is a clash: reported, never retyped or renamed.
// A mirror link whose "<Client> Signals" / "<Client> Campaigns" table is absent is a counted
// skip, as is anything that depends on it. The declared extras groups the launch picked
// (Scaffold Init, S.extras) walk with their table's own fields, deduplicated by name (Trustpilot
// Rating sits in two groups); an unpicked group is never touched. Emits {_done:true} when nothing
// is left, or when what is left can never resolve (those land in failed). A create that failed is
// never retried. A field kind the planner does not know is not a dependency: it fails on the first
// pass, naming the kind and the field, so a register mistake surfaces at once instead of hanging.
const sd=$getWorkflowStaticData('global'); const S=sd.scaffold;
const REG=$('Scaffold Register').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
S.pass=(S.pass||0)+1;
const done=(extra)=>{ S.pending=[]; return [{ json: Object.assign({ _done:true, pass:S.pass }, extra||{}), pairedItem:{ item:0 } }]; };
if(!tables){ S.failed.push('schema read, pass '+S.pass+': '+JSON.stringify(body).slice(0,200)); return done({ stuck:true }); }
if(S.pass>8){ S.failed.push('scaffold stopped after 8 passes with work still planned'); return done({ stuck:true }); }

const ci=(s)=>String(s||'').trim().toLowerCase();
const tableByName=(n)=>tables.find(t=>ci(t.name)===ci(n));
const fieldExact=(t,n)=>(t.fields||[]).find(f=>f.name===n);
const fieldCI=(t,n)=>(t.fields||[]).find(f=>ci(f.name)===ci(n));
const linkTo=(t,targetId)=>(t.fields||[]).find(f=>f.type==='multipleRecordLinks'&&f.options&&f.options.linkedTableId===targetId);
const registerNames=new Set(REG.tables.map(t=>ci(t.name)));
const mirrorTable=(kind)=>{
  const exact=tableByName(S.clientName+' '+kind); if(exact) return exact;
  const tail=new RegExp('(^|\\s)'+kind.toLowerCase()+'$');
  const found=tables.filter(t=>!registerNames.has(ci(t.name))&&tail.test(ci(t.name)));
  return found.length===1?found[0]:null;
};
const gone=(st)=>st==='failed'||st==='clash'||st==='skipped';
// Types a register field may already carry and still count as present. Never retyped.
const OK={ singleLineText:['singleLineText','multilineText','richText','email','url','phoneNumber'], multilineText:['multilineText','richText','singleLineText'], singleSelect:['singleSelect'], dateTime:['dateTime','date'], date:['date','dateTime'], number:['number','currency','percent'], checkbox:['checkbox'], url:['url','singleLineText'], formula:['formula'], link:['multipleRecordLinks'], mirrorLink:['multipleRecordLinks'], lookup:['multipleLookupValues'], mirrorLookup:['multipleLookupValues'], count:['count'], rollup:['rollup'] };
// Every field kind this planner knows, in one place, so a kind it does not know is caught by name
// instead of falling through. Two holes it closes, both paid for by the mirrorLookup kind added
// 2026-09-03: resolve() had no default branch, so an unknown kind slid into the lookup/count/rollup
// tail, read a missing `via`, resolved a table by undefined, deferred every pass and ended as
// `stuck: true` with a message naming nothing; and OK carried no entry for it, so the fallback
// compared the KIND to the Airtable TYPE and reported every already-correct field as a clash on
// every rerun. A kind outside this list is a register mistake, never a dependency that might
// arrive later, so it fails on the first pass with the kind and the field named.
const KINDS=['plain','formula','link','mirrorLink','mirrorLookup','lookup','count','rollup'];
const unknownKind=(k,where)=>'unknown field kind "'+String(k)+'" on register field '+where+'. This planner knows '+KINDS.join(', ')+'. Add a branch to resolve() and an accepted-types entry to OK (here and in the Onboard Client twin of this file) before the register uses it.';
const mark=(key,state,line)=>{ if(S.seen[key]) return; S.seen[key]=state; if(state==='existed') S.existed.push(key); else if(state==='skipped') S.skipped.push(line); else S.failed.push(line); };
// A register field's `description` travels to Airtable. It is the only place the register's own
// warnings reach a person who never opens this repo: Airtable renders a field description in the
// field editor and returns it from the meta API, and REGISTER.md was previously the end of the
// road for it (added 2026-09-03; the relevance placeholder warning was invisible in every base
// scaffolded before). Both create endpoints take the key, on a field body and on a table's field
// bodies, and the key is omitted entirely when the register declares none, so a field without a
// description is byte-for-byte the body it was before. Applied at the one resolve() call site
// below as well as here, so every kind travels, including a kind added later.
const describe=(o,f)=>{ if(f.description) o.description=f.description; return o; };
const plainBody=(f)=>{ const o={ name:f.name, type:f.type }; if(f.options) o.options=f.options; return describe(o,f); };
// The picked extras groups' fields for a table, after its own register fields, one field per name.
const picked=new Set(S.extras||[]);
const fieldsOf=(T)=>{ const seen=new Set(T.fields.map(f=>f.name)); const out=T.fields.slice(); for(const g of (REG.extras||[])){ if(g.table!==T.name||!picked.has(g.group)) continue; for(const f of g.fields){ if(seen.has(f.name)) continue; seen.add(f.name); out.push(f); } } return out; };

function resolve(f,T,t){
  if(f.kind==='plain') return { body: plainBody(f) };
  if(f.kind==='formula'){
    let formula=f.formula;
    for(const ref of f.refs||[]){
      const rf=fieldExact(t,ref);
      if(!rf){ const st=S.seen[T.name+'.'+ref]; return gone(st)?{ skip:'references '+ref+', which '+st }:{ defer:'waits for '+ref }; }
      formula=formula.split('{'+ref+'}').join('{'+rf.id+'}');
    }
    return { body:{ name:f.name, type:'formula', options:{ formula:formula } } };
  }
  if(f.kind==='link'){
    const target=tableByName(f.table);
    if(!target){ const st=S.seen[f.table+'.(table)']; return gone(st)?{ skip:'links to '+f.table+', which '+st }:{ defer:'waits for table '+f.table }; }
    return { body:{ name:f.name, type:'multipleRecordLinks', options:{ linkedTableId: target.id } } };
  }
  if(f.kind==='mirrorLink'){
    const m=mirrorTable(f.mirror);
    if(!m) return { skip:'no "'+S.clientName+' '+f.mirror+'" table in the base yet; the Operator syncs the mirror from the Hub, then adds this link by hand' };
    return { body:{ name:f.name, type:'multipleRecordLinks', options:{ linkedTableId: m.id } } };
  }
  if(f.kind==='mirrorLookup'){
    // Like a lookup, but through the mirror link on this table, not through the Companies link:
    // the mirror is found by its own name, the link to it by that table's id, the source column
    // inside the mirror by name. The mirror is the Operator's synced table, so a missing mirror
    // and a mirror without the column are both counted skips, never a wait that can never resolve.
    const m=mirrorTable(f.mirror);
    if(!m) return { skip:'no "'+S.clientName+' '+f.mirror+'" table in the base yet; the Operator syncs the mirror from the Hub, then adds this lookup by hand' };
    const govKey=T.name+'.'+f.mirror;
    const link=linkTo(t,m.id);
    if(!link){ const st=S.seen[govKey]; return gone(st)?{ skip:'needs the link '+govKey+', which '+st }:{ defer:'waits for the link '+govKey }; }
    const src=fieldExact(m,f.field);
    if(!src) return { skip:'looks up '+f.field+' on "'+m.name+'", which the synced mirror does not carry; the Operator adds the column to the sync, then adds this lookup by hand' };
    return { body:{ name:f.name, type:'multipleLookupValues', options:{ recordLinkFieldId: link.id, fieldIdInLinkedTable: src.id } } };
  }
  // The default branch. Only lookup, count and rollup reach the tail below; anything else is a
  // register mistake and fails here by name rather than resolving a table by undefined.
  if(f.kind!=='lookup'&&f.kind!=='count'&&f.kind!=='rollup') return { fail: unknownKind(f.kind, T.name+'.'+f.name) };
  // lookup, count, rollup: through the link between this table and f.via, found by table id.
  const target=tableByName(f.via);
  const govKey=(f.kind==='lookup')?(T.name+'.'+f.via):(f.via+'.'+T.name);
  if(!target){ const st=S.seen[f.via+'.(table)']; return gone(st)?{ skip:'needs table '+f.via+', which '+st }:{ defer:'waits for table '+f.via }; }
  const link=linkTo(t,target.id);
  if(!link){ const st=S.seen[govKey]; return gone(st)?{ skip:'needs the link '+govKey+', which '+st }:{ defer:'waits for the link '+govKey }; }
  if(f.kind==='count') return { body:{ name:f.name, type:'count', options:{ recordLinkFieldId: link.id } } };
  const src=fieldExact(target,f.field);
  if(!src){ const st=S.seen[f.via+'.'+f.field]; return gone(st)?{ skip:'looks up '+f.via+'.'+f.field+', which '+st }:{ defer:'waits for '+f.via+'.'+f.field }; }
  if(f.kind==='lookup') return { body:{ name:f.name, type:'multipleLookupValues', options:{ recordLinkFieldId: link.id, fieldIdInLinkedTable: src.id } } };
  return { body:{ name:f.name, type:'rollup', options:{ recordLinkFieldId: link.id, fieldIdInLinkedTable: src.id, formula: f.formula } } };
}

const urlTables='https://api.airtable.com/v0/meta/bases/'+S.base+'/tables';
const calls=[]; const deferred=[];
for(const T of REG.tables){
  const t=tableByName(T.name);
  const tkey=T.name+'.(table)';
  const fields=fieldsOf(T);
  if(!t){
    if(gone(S.seen[tkey])) continue;
    const waits=(T.after||[]).filter(d=>{
      const dt=tableByName(d.table);
      if(!dt) return !gone(S.seen[d.table+'.(table)']);
      if(!d.field||fieldExact(dt,d.field)) return false;
      return !gone(S.seen[d.table+'.'+d.field]);
    });
    if(waits.length){ deferred.push({ key:tkey, why:'waits for '+waits.map(d=>d.table+(d.field?'.'+d.field:'')).join(', ') }); continue; }
    const plain=fields.filter(f=>f.kind==='plain');
    const primary=plain.find(f=>f.name===T.primary)||plain[0];
    const tableFields=[primary].concat(plain.filter(f=>f!==primary)).map(plainBody);
    calls.push({ key:tkey, table:T.name, name:'(table)', kind:'table', fieldNames:tableFields.map(f=>f.name), method:'POST', url:urlTables, body:{ name:T.name, fields:tableFields } });
    continue;
  }
  mark(tkey,'existed');
  for(const f of fields){
    const key=T.name+'.'+f.name;
    // Ahead of the existence check, so an unknown kind fails once and clearly instead of reporting
    // an already-correct column as a clash on every rerun.
    if(KINDS.indexOf(f.kind)<0){ mark(key,'failed', key+': '+unknownKind(f.kind, key)); continue; }
    const expect=(f.kind==='plain')?f.type:f.kind;
    const ex=fieldExact(t,f.name);
    // An existing field is left alone, its description included: the planner creates and never
    // patches, and the description is exactly the column an Operator edits per client. The
    // relevance placeholder is the case that decides it. The register's description says "replace
    // this with your own buyer rule"; the client whose rule already replaced it has written what
    // their rule actually does, and the planner cannot retype the formula either, so pushing the
    // register's text back would overwrite a true note with a stale warning on every rerun. A
    // register description reaches a base that already carries the field by the Operator's hand.
    if(ex){
      if((OK[expect]||[expect]).indexOf(ex.type)>=0) mark(key,'existed');
      else mark(key,'clash', key+': exists as '+ex.type+', the register wants '+expect+' (left alone, never retyped)');
      continue;
    }
    const cv=fieldCI(t,f.name);
    if(cv){ mark(key,'clash', key+': the table carries "'+cv.name+'", a case variant (left alone, never renamed)'); continue; }
    if(gone(S.seen[key])) continue;
    const spec=resolve(f,T,t);
    if(spec.fail){ mark(key,'failed', key+': '+spec.fail); continue; }
    if(spec.skip){ mark(key,'skipped', key+': '+spec.skip); continue; }
    if(spec.defer){ deferred.push({ key:key, why:spec.defer }); continue; }
    calls.push({ key:key, table:T.name, name:f.name, kind:f.kind, method:'POST', url:urlTables+'/'+t.id+'/fields', body:describe(spec.body,f) });
  }
}
if(!calls.length){
  for(const d of deferred) mark(d.key,'failed', d.key+': never became creatable ('+d.why+')');
  return done({ stuck: deferred.length>0 });
}
S.pending=calls.map(c=>({ key:c.key, table:c.table, name:c.name, kind:c.kind, fieldNames:c.fieldNames||[] }));
return calls.map(c=>({ json: c, pairedItem:{ item:0 } }));

// Collect Scaffold Results: pairs each meta-API response with the call Plan Scaffold Pass
// queued (same order, one response per call), records what was created and what failed, and
// hands one item back to the schema read for the next pass. A create that failed is marked so
// it is never retried; whatever depended on it becomes a counted skip on the next pass.
const sd=$getWorkflowStaticData('global'); const S=sd.scaffold;
const pend=S.pending||[]; const items=$input.all();
items.forEach((it,i)=>{
  const p=pend[i]; if(!p) return;
  const j=it.json||{}; const b=(j.body!==undefined)?j.body:j;
  let err='';
  if(b&&b.error) err=(typeof b.error==='string')?b.error:(b.error.message||b.error.type||JSON.stringify(b.error));
  else if(j.error&&!b.id) err=String(j.error.message||j.error);
  if(!err&&b&&b.id){
    S.seen[p.key]='created';
    S.created.push({ table:p.table, name:p.name, kind:p.kind, id:b.id, how:(p.kind==='table')?'table':'field' });
    if(p.kind==='table'){ for(const n of p.fieldNames||[]){ S.seen[p.table+'.'+n]='created'; S.created.push({ table:p.table, name:n, kind:'plain', id:'', how:'withTable' }); } }
  } else {
    S.seen[p.key]='failed';
    S.failed.push(p.key+': '+(err||'no id in the response').slice(0,200));
  }
});
if(items.length!==pend.length) S.failed.push('pass '+S.pass+': '+pend.length+' calls queued, '+items.length+' responses came back');
S.pending=[];
return [{ json:{ pass:S.pass, created:S.created.length, failed:S.failed.length }, pairedItem:{ item:0 } }];

// Build Run Log: one row per onboarding, upserted on Execution ID back onto the launch row that
// started it, to the logging standard. Status is computed from failed[] (a scaffold create that
// failed, a clash, an unresolved table id, a registry write that did not come back with a record);
// skips (what the template already carried, what waits for a mirror, a launch row that named no
// contacts) are separate lines and never errors.
//
// The Description is deliberately two halves. The first says what the machine did. The second is
// the Operator's checklist: the four acts no API can perform, each with the exact thing to do and
// why it cannot be automated. It is written to be worked from, top to bottom, without leaving the
// row.
const sd = $getWorkflowStaticData('global');
const p = $('Launch Params').first().json || {};
const name = p.clientName || '(unknown)';
let v = {}; try { v = $('Build Client Vars').first().json || {}; } catch (e) {}
let folderId = ''; try { folderId = $('Create Client Folder').first().json.id || ''; } catch (e) {}
let channelId = ''; try { channelId = $('Create Slack Channel').first().json.id || ''; } catch (e) {}
let reg = {}; try { reg = $('Build Registry Row').first().json || {}; } catch (e) {}

// The registry upsert's own answer. Airtable returns records[] on both the create and the update
// leg; no id back means the row is not there, whatever the status code said.
const up = $input.first().json || {};
const upBody = (up.body !== undefined) ? up.body : up;
const recs = (upBody && Array.isArray(upBody.records)) ? upBody.records : [];
const regRec = (recs[0] && recs[0].id) || '';
const created = ((upBody && Array.isArray(upBody.createdRecords)) ? upBody.createdRecords : []).length > 0;

const failed = [];
if (!folderId) failed.push('Drive: no client folder id came back; the anatomy may be incomplete');
if (!channelId) failed.push('Slack: no channel id came back for ' + (v.channelName || '(unnamed)'));
for (const m of (reg.missing || [])) failed.push('Registry: ' + m);
if (!regRec) {
  const e = (upBody && upBody.error) || (up && up.error) || '';
  failed.push('Registry: the Clients upsert returned no record' + (e ? ': ' + (typeof e === 'object' ? (e.message || JSON.stringify(e)) : String(e)).slice(0, 200) : ''));
}
const S = sd.scaffold || null;
if (!S) failed.push('scaffold state missing: Scaffold Init never ran');
for (const f of (S && S.failed) || []) failed.push(f);

const emails = v.emails || [];
const skips = [];
if (!(p.contactIds || []).length) skips.push('Drive share: the launch row named no Contact, so the Shared folder was shared with nobody');
else if (!emails.length) skips.push('Drive share: the ' + p.contactIds.length + ' contact(s) on the launch row carry no email address');
if (!reg.sharedCompanies) skips.push('Registry: ClayrootsCompaniesSharedView left empty, the Companies table description carries no share link');
if (!reg.sharedPeople) skips.push('Registry: ClayrootsPeopleSharedView left empty, the People table description carries no share link');

const lines = [
  '**' + name + ': Rootworks infrastructure ' + (failed.length ? 'stood up with ' + failed.length + ' error' + (failed.length === 1 ? '' : 's') : 'stood up') + '**',
  '',
  '**Scope:** one client, ' + name + ', on the duplicated template base ' + p.base,
  '',
  '**Built**',
  '- **Drive:** client folder ' + (folderId || '(none)') + ', full anatomy plus the Overrides stub; Shared shared with ' + (emails.length ? emails.length + ' contact(s): ' + emails.join(', ') : 'nobody'),
  '- **Slack:** ' + (v.channelName || '') + ' created (' + (channelId || 'none') + '), Operator invited',
  '- **Registry:** Clients row ' + (regRec || '(none)') + ' ' + (regRec ? (created ? 'created' : 'filled in place') : 'NOT written') + ', fields set: ' + ((reg.written || []).join(', ') || 'none'),
  '- **Table ids resolved from the base:** Companies ' + (reg.companiesTableId || '(none)') + ', People ' + (reg.peopleTableId || '(none)'),
];
if (S) {
  const c = S.created || [];
  const nFields = c.filter(x => x.name !== '(table)').length;
  const nTables = c.filter(x => x.name === '(table)').length;
  lines.push('', '**Scaffold** (base ' + S.base + ', ' + S.pass + ' schema pass' + (S.pass === 1 ? '' : 'es') + ', ' + nFields + ' field' + (nFields === 1 ? '' : 's') + ' and ' + nTables + ' table' + (nTables === 1 ? '' : 's') + ' created)');
  lines.push('**Extras picked:** ' + ((S.extras || []).length ? S.extras.join(', ') : 'none, the register core only, which the template already carries'));
  for (const T of ['Companies', 'People', 'DNC']) {
    const tbl = c.find(x => x.table === T && x.name === '(table)');
    const withTable = c.filter(x => x.table === T && x.name !== '(table)' && (x.how === 'base' || x.how === 'withTable')).map(x => x.name);
    const added = c.filter(x => x.table === T && x.name !== '(table)' && x.how === 'field').map(x => x.name);
    let how = tbl ? 'created (the base did not carry it)' : (S.seen[T + '.(table)'] === 'existed' ? 'came with the template' : 'not created');
    if (withTable.length) how += ', ' + withTable.length + ' fields (' + withTable.join(', ') + ')';
    if (added.length) how += '; fields added (' + added.length + '): ' + added.join(', ');
    if (!withTable.length && !added.length) how += '; nothing added';
    lines.push('- **' + T + ':** ' + how);
  }
  lines.push('', 'Skipped (' + S.existed.length + ', already on the base, left alone): ' + (S.existed.length ? S.existed.length + ' register columns' : 'nothing pre-existed'));
  if (S.skipped.length) { lines.push('', 'Skipped (' + S.skipped.length + ', not creatable yet):'); for (const s of S.skipped) lines.push('- ' + s); }
}
if (skips.length) { lines.push('', 'Skipped (' + skips.length + '):'); for (const s of skips) lines.push('- ' + s); }
if (failed.length) { lines.push('', '**Failed (' + failed.length + ')**'); for (const f of failed) lines.push('- ' + f); }

lines.push(
  '',
  '**Operator, the four hand acts.** Everything above is done. None of these four can be: Airtable has no API for any of them. Work them top to bottom; 3 depends on 2.',
  '',
  '1. **The relevance rule, on Companies and People.** Both ship from the template with a placeholder formula (Companies `IF(OR({manually_approved}, {public_emails_clean} != ""), 1, 0)`, People `IF(OR({manually_approved}, FALSE()), 1, 0)`). Replace each with ' + name + '\'s buyer rule. Every view that feeds a campaign reads relevance, so until this is done the People side cuts everyone. The meta API can rename a field, never re-express a formula.',
  '',
  '2. **The two mirrors.** In base ' + p.base + ', Add table > Sync from another base, from the Hub (appQG6dK0FIOhTxOl): the Campaigns view filtered to ' + name + ' as **"' + name + ' Campaigns"**, and the Signals view filtered to ' + name + ' as **"' + name + ' Signals"**, each with Hub Record ID included. A sync is an interface act; there is no endpoint for one.',
  '',
  '3. **The mirror columns, which 2 unlocks.** Campaigns (link) and Sequencers (lookup through it) on both Companies and People, Signals (link) on Companies and Signals (lookup) on People. The scaffold skipped exactly these this run because the mirrors did not exist yet. Fastest path: create a Hub Automations row with Automation = Scaffold Client Base and Client = ' + name + ', which fires POST /webhook/launch-scaffold-client-base and runs the same scaffold again; with the mirrors present it creates all of them and writes its own row. By hand is the same six columns.',
  '',
  '4. **The two share links.** Share the Companies table and the People table, then either paste each link into that table\'s description in the base and rerun this machine, or paste them straight into this client\'s Clients row, ClayrootsCompaniesSharedView and ClayrootsPeopleSharedView. That is the surface we hand the client. No API creates a share.',
);

const started = Date.parse(p.startedAt || '') || sd.runStartedAt || Date.now();
const row = {
  'Execution ID': String($execution.id),
  'Automation': 'Create Client Rootworks Infrastructure',
  'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
  'Run at': p.startedAt || new Date().toISOString(),
  'Records In': 1,
  'Records Out': 1,
  'Errors': failed.length,
  'Target': p.base || '',
  'Trigger': 'form',
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Duration s': Math.round((Date.now() - started) / 1000),
  'Description': lines.join('\n'),
};
// Client is attached only when the registry row is actually in hand; an empty link array has
// wiped correct attachments on pre-created rows before.
if (regRec) row['Client'] = [regRec];
return [{ json: row }];

// Launch Params: the launch row is the whole contract for standing up a new client's Rootworks
// infrastructure. Four fields are read from it and nothing else:
//   Build name         the client's name, exactly as the registry is to carry it. It is also the
//                      merge key of the registry upsert and the stem of the Drive folder, the
//                      Slack channel and the two mirror table names, so it is spelled once, here.
//   Clayroots Base ID  the base the Operator just made by duplicating CLAYROOTS SCHEMA
//                      (appMhfP6GeR5WeSiC). This machine no longer creates a base: Airtable
//                      cannot duplicate one by API, and duplicating in the interface is what
//                      carries all 17 views with their filters, sorts and field visibility.
//   Extras             the declared extras groups to add to Companies and People. The template
//                      deliberately carries none; extras are picked per client at onboarding.
//   Contact            the client's own contacts. Their email addresses get writer access to the
//                      Drive Shared folder. Empty is valid and lands as a named skip, not an error.
// Both are validated here, before a single Drive folder, Slack channel or Airtable column exists,
// so a typo on the row costs nothing but the row. Resets the run's state at the trigger.
const sd = $getWorkflowStaticData('global');
sd.scaffold = null;
sd.runStartedAt = Date.now();
const rec = $('Fetch Launch Record').first().json || {};
const f = rec.fields || {};
const arr = (v) => Array.isArray(v) ? v : (v == null || v === '' ? [] : [v]);
const idOf = (x) => String((x && typeof x === 'object') ? (x.id || x.name || '') : x).trim();

const clientName = String(f['Build name'] || '').trim();
const base = String(f['Clayroots Base ID'] || '').trim();
if (!clientName) {
  throw new Error('Launch record ' + rec.id + ' has no Build name. That field is the client\'s name; nothing was created.');
}
if (!/^app[A-Za-z0-9]{14}$/.test(base)) {
  throw new Error('Launch record ' + rec.id + ' has no valid Clayroots Base ID ("' + base + '"). Duplicate the CLAYROOTS SCHEMA template (appMhfP6GeR5WeSiC) first and paste the new base id onto the row; nothing was created.');
}

const extras = arr(f['Extras']).map(idOf).filter(Boolean);
const contactIds = arr(f['Contact']).map(idOf).filter(Boolean);
// The Contacts search runs whatever this says. FALSE() when the row names nobody, so the node
// still emits and the Drive share leg simply has no one to invite.
const formula = contactIds.length
  ? 'OR(' + contactIds.map((id) => "RECORD_ID()='" + id + "'").join(',') + ')'
  : 'FALSE()';

return [{ json: {
  clientName: clientName,
  base: base,
  extras: extras,
  contactIds: contactIds,
  formula: formula,
  _launchRecordId: rec.id || '',
  startedAt: new Date().toISOString(),
} }];

// Build Registry Row: the Hub Clients write, built from what this run actually produced, sent as
// one Airtable upsert (PATCH with performUpsert) rather than a create, so the row is created or
// filled: a client the Operator already opened a registry row for is filled in place, matched on
// the Client name, and a client with no row yet gets one. That is why the client's name is spelled
// once, on the launch row.
//
// The table ids are RESOLVED, never taken on trust: this node reads the new base's own schema
// (AT Read Final Schema, run after the scaffold) and finds Companies and People by name. A
// duplicated base has fresh table ids every time, so being told them would be a standing lie.
//
// What lands, by Hub field:
//   Client                        fldrPOm3IINTtktbs   the merge key
//   driveMainFolderID             fldSHZVcIgGDmZOpv
//   Slack Channel ID              fldP5V8vAPVHvpuut
//   Clayroots Base ID             fldRAiazbtIutFb7s
//   ClayrootsCompaniesTableID     fldHhhOlD6RSzYi3p
//   ClayrootsPeopleTableID        fldAkkVBD6fLBA9my
//   ClayrootsCompaniesSharedView  fldu7gE5tnsJsS7qc   only when the table description carries it
//   ClayrootsPeopleSharedView     fldVXKc6ToYeWNGEo   only when the table description carries it
//
// The two share links have no creation endpoint anywhere in the Airtable API, so the only way one
// can reach this node is the Operator pasting it into that table's description in the base, the
// convention these two fields replaced. Read from there when it is there; named in the run row's
// checklist when it is not. A value we do not have is OMITTED, never written as an empty string
// over something real: an upsert writes the same keys on create and on update.
const p = $('Launch Params').first().json || {};
const r = $input.first().json || {};
const body = (r.body !== undefined) ? r.body : r;
const tables = (body && Array.isArray(body.tables)) ? body.tables : [];

const ci = (s) => String(s || '').trim().toLowerCase();
const byName = (n) => tables.find(t => ci(t.name) === ci(n));
const shareIn = (t) => {
  const m = String((t && t.description) || '').match(/https:\/\/airtable\.com\/\S+/);
  return m ? m[0].replace(/[)\].,]+$/, '') : '';
};

const companies = byName('Companies');
const people = byName('People');
const missing = [];
if (!tables.length) missing.push('the base schema could not be read at the close, so no table id was resolved');
if (tables.length && !companies) missing.push('no Companies table in ' + p.base);
if (tables.length && !people) missing.push('no People table in ' + p.base);

let folderId = ''; try { folderId = $('Create Client Folder').first().json.id || ''; } catch (e) {}
let channelId = ''; try { channelId = $('Create Slack Channel').first().json.id || ''; } catch (e) {}

const fields = { 'Client': p.clientName, 'Clayroots Base ID': p.base };
if (folderId) fields['driveMainFolderID'] = folderId;
if (channelId) fields['Slack Channel ID'] = channelId;
if (companies) fields['ClayrootsCompaniesTableID'] = companies.id;
if (people) fields['ClayrootsPeopleTableID'] = people.id;
const shareC = companies ? shareIn(companies) : '';
const shareP = people ? shareIn(people) : '';
if (shareC) fields['ClayrootsCompaniesSharedView'] = shareC;
if (shareP) fields['ClayrootsPeopleSharedView'] = shareP;

return [{ json: {
  url: 'https://api.airtable.com/v0/appQG6dK0FIOhTxOl/tblK0nCoNVvFf5SPa',
  body: { performUpsert: { fieldsToMergeOn: ['Client'] }, records: [{ fields: fields }], typecast: true },
  companiesTableId: companies ? companies.id : '',
  peopleTableId: people ? people.id : '',
  sharedCompanies: shareC,
  sharedPeople: shareP,
  written: Object.keys(fields),
  missing: missing,
}, pairedItem: { item: 0 } }];
